def make_svg(ticket_id: str, title: str, app: str, severity: str, num: int,
             feature: str, platform: str, device: str, osver: str, market: str) -> str:
    colors = {"Critical":"#c95d53", "High":"#dd8750", "Medium":"#d3a747", "Low":"#4e9b72"}
    accent = colors[severity]
    esc = lambda value: escape(str(value), quote=True)
    feature_key = feature.lower()
    app_title = esc(app)
    title_short = esc(title[:65])
    device_line = esc(f"{device} · {osver}")
    market_line = esc(f"{market} · {ticket_id} · build 8.{41 + num % 9}.{num % 7}")
    shell = f'<svg xmlns="http://www.w3.org/2000/svg" width="900" height="560" viewBox="0 0 900 560"><rect width="900" height="560" fill="#e9eeea"/><rect x="68" y="20" width="764" height="520" rx="28" fill="#fff"/><rect x="68" y="20" width="764" height="50" rx="28" fill="#17372a"/><circle cx="96" cy="45" r="5" fill="#f17e77"/><circle cx="113" cy="45" r="5" fill="#e9bf54"/><circle cx="130" cy="45" r="5" fill="#6bd18e"/><text x="450" y="50" text-anchor="middle" fill="#edf7f0" font-family="Arial" font-size="15">{app_title} · {esc(feature.title())} · {esc(platform)}</text><text x="104" y="101" fill="#78867e" font-family="Arial" font-size="12">{esc(ticket_id)} · {device_line}</text>'
    footer = f'<rect x="104" y="475" width="692" height="1" fill="#e5ebe6"/><text x="104" y="502" fill="#7f8b83" font-family="Arial" font-size="11">{market_line}</text></svg>'
    if platform == "Backend":
        content = f'<rect x="104" y="119" width="170" height="325" rx="12" fill="#f5f8f5"/><text x="124" y="151" fill="#34463b" font-family="Arial" font-size="14" font-weight="bold">Service health</text><text x="124" y="190" fill="#87938b" font-family="Arial" font-size="11">{esc(feature.title())} API</text><text x="124" y="234" fill="{accent}" font-family="Arial" font-size="27" font-weight="bold">{504 if severity == "Critical" else 429 if "merchant" in feature_key else 5 + num % 9}%</text><text x="124" y="254" fill="#7c8981" font-family="Arial" font-size="10">error / queue signal</text><rect x="124" y="279" width="128" height="8" rx="4" fill="#e3ebe4"/><rect x="124" y="279" width="{48 + num % 70}" height="8" rx="4" fill="{accent}"/><text x="124" y="324" fill="#34463b" font-family="Arial" font-size="11">{title_short}</text><rect x="292" y="119" width="504" height="203" rx="12" fill="#fbfcfb" stroke="#e7ece8"/><text x="316" y="150" fill="#34463b" font-family="Arial" font-size="14" font-weight="bold">Live service telemetry</text><polyline points="316,270 355,245 394,255 433,205 472,224 511,180 550,212 589,157 628,197 667,176 706,228 745,168 774,188" fill="none" stroke="{accent}" stroke-width="4"/><line x1="316" y1="280" x2="774" y2="280" stroke="#e6ebe7"/><rect x="292" y="338" width="504" height="106" rx="12" fill="#17251f"/><text x="316" y="365" fill="#a8d5b5" font-family="monospace" font-size="11">{esc(feature)}-service · correlation_id={esc(ticket_id.lower())}</text><text x="316" y="391" fill="#f29a8c" font-family="monospace" font-size="12">{title_short}</text><text x="316" y="419" fill="#9ab09f" font-family="monospace" font-size="10">request failed · inspect attached application.log</text>'
    elif feature_key in ("maps", "routing", "navigation"):
        content = f'<rect x="104" y="119" width="692" height="325" rx="14" fill="#eaf2e9"/><path d="M120 195 C235 150 290 264 392 218 S560 149 777 198 M115 334 C230 282 344 360 448 311 S637 279 783 340 M230 127 C250 220 204 282 245 434 M565 124 C520 204 611 287 566 435" fill="none" stroke="#c4d5c8" stroke-width="18"/><path d="M121 333 C255 286 343 353 447 310 S610 274 767 327" fill="none" stroke="{accent}" stroke-width="7" stroke-dasharray="12 8"/><circle cx="450" cy="310" r="16" fill="#fff" stroke="{accent}" stroke-width="7"/><rect x="512" y="136" width="260" height="78" rx="12" fill="#fff"/><text x="532" y="167" fill="#34463b" font-family="Arial" font-size="13" font-weight="bold">Route issue detected</text><text x="532" y="191" fill="#748279" font-family="Arial" font-size="11">{title_short}</text><rect x="124" y="365" width="230" height="60" rx="12" fill="#fff"/><text x="144" y="391" fill="#34463b" font-family="Arial" font-size="12" font-weight="bold">Route · {esc(market)}</text><text x="144" y="412" fill="{accent}" font-family="Arial" font-size="11">Recalculating trip…</text>'
